func (m *ignoreMatcher) loadContent(content string, includeMode bool) error {
	scanner := bufio.NewScanner(strings.NewReader(content))
	for scanner.Scan() {
		rule, ok := parseIgnoreRule(scanner.Text(), includeMode)
		if ok {
			m.rules = append(m.rules, rule)
		}
	}
	return scanner.Err()

