// Simulate the proposed fix: on an INDENTED line (not a fence), only treat it as an
// invocation when it actually names `entire graph <cmd>` — no sectionCommand fallback.
func parseGuideClaimsFixed(guide string) (flags []guideClaim) {
	inFence := false
	sectionCommand := ""
	for i, line := range strings.Split(guide, "\n") {
		if strings.HasPrefix(line, "#") {
			sectionCommand = ""
			if m := guideHeadingRE.FindStringSubmatch(line); m != nil {
				sectionCommand = m[1]
			}
		}
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "```") {
			inFence = !inFence
			continue
		}
		switch {
		case inFence:
			flags = append(flags, invocationFlagClaims(line, sectionCommand, i+1)...)
		case guideIndentedCodeRE.MatchString(line):
			if guideCommandRE.MatchString(line) { // <-- the fix
				flags = append(flags, invocationFlagClaims(line, sectionCommand, i+1)...)
			}
		default:
			for _, m := range guideInlineRE.FindAllStringSubmatch(line, -1) {
				flags = append(flags, invocationFlagClaims(m[1], sectionCommand, i+1)...)
			}
		}
	}
	return flags
}

func TestZZFixParity(t *testing.T) {
	_, cur, _, _ := parseGuideClaims(agentGuide)
	fixed := parseGuideClaimsFixed(agentGuide)
	t.Logf("CONST     current=%d fixed=%d", len(cur), len(fixed))

	raw, _ := os.ReadFile("../../AGENTS.md")
	_, acur, _, _ := parseGuideClaims(string(raw))
	afixed := parseGuideClaimsFixed(string(raw))
	t.Logf("AGENTS.md current=%d fixed=%d", len(acur), len(afixed))

	// The false positive that motivated the fix.
	bad := "### 🕸️ neighbors — *who calls this*\n- see also\n    --index-all-files for search"
	_, before, _, _ := parseGuideClaims(bad)
	after := parseGuideClaimsFixed(bad)
