				line += " file=" + event.Path
			}
			fmt.Fprintln(opts.Stderr, line)
		}
	}
	result, err := sem.AnalyzeGitRangeWithOptions(ctx, repo, base, head, paths, analyzeOptions)
	if err != nil {
		return err
	}
	return printResult(opts.Stdout, result, flags.JSON)
}

