// TestManifestImportFilesCoverReads binds manifestImportFiles to the readContent calls in
// buildManifestImportResolver by reading the source, so the list cannot silently fall behind a
// newly consulted manifest. The two exist apart for a reason worth protecting: the cache gate
// asks "can a change to this path alter what I index?", and for a manifest the answer is yes even
// though its extension says the file is never parsed.
func TestManifestImportFilesCoverReads(t *testing.T) {
	fileSet := token.NewFileSet()
	parsed, err := parser.ParseFile(fileSet, "provider.go", nil, 0)
	if err != nil {
		t.Fatalf("parse provider.go: %v", err)
	}

	var read []string
	ast.Inspect(parsed, func(node ast.Node) bool {
		decl, ok := node.(*ast.FuncDecl)
		if !ok || decl.Name.Name != "buildManifestImportResolver" {
			return true
		}
		ast.Inspect(decl.Body, func(inner ast.Node) bool {
			call, ok := inner.(*ast.CallExpr)
			if !ok {
				return true
			}
			ident, ok := call.Fun.(*ast.Ident)
			if !ok || ident.Name != "readContent" || len(call.Args) != 1 {
				return true
			}
			literal, ok := call.Args[0].(*ast.BasicLit)
			if !ok || literal.Kind != token.STRING {
				return true
			}
			name, err := strconv.Unquote(literal.Value)
			if err != nil {
				t.Fatalf("unquote %s: %v", literal.Value, err)
			}
			read = append(read, name)
			return true
		})
		return false
	})

	if len(read) == 0 {
		t.Fatal("found no readContent string literals in buildManifestImportResolver; this guard has stopped guarding")
	}
	for _, name := range read {
		if !isManifestImportFile(name) {
			sort.Strings(read)
			t.Errorf("buildManifestImportResolver reads %q, but manifestImportFiles does not list it: "+
				"a working-tree edit to that manifest would be forgiven by the snapshot cache and serve a "+
				"stale resolver (reads: %v)", name, read)
		}
	}
}
